package com.huy.enterprise.inventory; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/warehouses") @RequiredArgsConstructor public class WarehouseController {private final WarehouseService service;@GetMapping List<WarehouseResponse> all(){return service.all();}@GetMapping("/{id}") WarehouseResponse get(@PathVariable UUID id){return service.get(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) WarehouseResponse create(@Valid @RequestBody WarehouseRequest r){return service.save(null,r);}@PutMapping("/{id}") WarehouseResponse update(@PathVariable UUID id,@Valid @RequestBody WarehouseRequest r){return service.save(id,r);}}
